<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare("SELECT * FROM users WHERE email=?");$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['name']=$u['name'];$_SESSION['role']=$u['role'];header('Location: index.php');exit;}$err='Email or password is incorrect.';}layout_start('Welcome back');?><section class="auth"><p>Sign in to your community reading space.</p><?php if($err):?><p class="error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Sign in</button></form><p>New reader? <a href="register.php">Create a student account</a></p><p class="muted">First install? <a href="setup.php">Set up administrator</a></p></section><?php layout_end();?>